      });
      s.createdAt = new Date(Date.UTC(2026, 0, 1) + ((i * 7919) % 5000) * 60000).toISOString();
    }
  });

  after(async () => {
    await srv.close();
  });

  it('returns the newest shipments first and honours limit', async () => {
    const res = await api(srv.url, 'GET', '/shipments?limit=100');
    assert.equal(res.body.items.length, 100);
    const dates: string[] = res.body.items.map((i: { created_at: string }) => i.created_at);
    assert.deepEqual([...dates].sort().reverse(), dates);
